69	  const { data, error } = await supabase.from("agent_proposals").update({ status: "rejected", decided_at: new Date().toISOString(), result: { replaced: true } })
70	    .eq("workspace_id", workspaceId).eq("chat_request_id", requestId).in("status", OPEN).select("id");
71	  if (error) throw new Error(error.message);
72	  return (data ?? []).length;
73	}
74	
