1	import { createHash, randomBytes, randomUUID } from "node:crypto";
2	import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
3	import path from "node:path";
4	import { z } from "zod";
5	import { decryptToken, encryptToken } from "@/lib/bank/token-crypto";
6	import { serviceKey } from "@/lib/service-keys";
7	
8	// "Sign in with ChatGPT" for open-source, locally hosted apps: the owner's ChatGPT plan pays for
9	// AI requests instead of an API key. Dynamic client registration with PKCE, no client secret.
10	// Docs: https://developers.openai.com/siwc/token-sharing-open-source/sign-in
11	const AUTH = "https://auth.openai.com/api/accounts";
12	const RESOURCE = "https://api.openai.com/v1";
13	const SCOPE = "openid profile email offline_access resource.invoke chatgpt.tokens.use.direct";
14	const PLAN_SCOPE = "chatgpt.tokens.use.direct";
15	const file = () => path.join(process.env.MONEO_DATA_DIR ?? path.join(process.cwd(), ".data"), "chatgpt.json");
16	const AAD = "moneo:chatgpt";
17	
18	export type AiSource = "chatgpt" | "claude" | "api_key";
19	const tokensSchema = z.object({ accessToken: z.string(), refreshToken: z.string().nullable(), expiresAt: z.number(), scopes: z.array(z.string()) });
20	const stateSchema = z.object({
21	  hostId: z.string().transform(value => z.uuid().safeParse(value).success ? `urn:uuid:${value}` : value),
22	  // Which one pays when both are set up; the owner picks it in Settings.
23	  source: z.enum(["chatgpt", "claude", "api_key"]).default("chatgpt"),
24	  account: z.object({ clientId: z.string(), email: z.string().nullable(), idToken: z.string().nullable(), tokens: tokensSchema }).nullable().default(null),
25	  pending: z.object({ state: z.string(), verifier: z.string(), redirectUri: z.string(), clientId: z.string(), createdAt: z.number() }).nullable().default(null),
26	});
27	type State = z.infer<typeof stateSchema>;
28	type Tokens = z.infer<typeof tokensSchema>;
29	
30	export class ChatGPTError extends Error {}
31	
32	// Tokens are sealed with the app's encryption key, so the file alone does not leak them.
33	async function load(): Promise<State> {
34	  try { return stateSchema.parse(JSON.parse(decryptToken(await readFile(file(), "utf8"), AAD))); }
35	  catch (error) {
36	    if ((error as NodeJS.ErrnoException).code === "ENOENT") return stateSchema.parse({ hostId: `urn:uuid:${randomUUID()}` });
37	    throw error;
38	  }
39	}
40	async function save(state: State) {
41	  const target = file();
42	  await mkdir(path.dirname(target), { recursive: true });
43	  const temp = `${target}.${process.pid}.tmp`;
44	  await writeFile(temp, encryptToken(JSON.stringify(state), AAD), { mode: 0o600 });
45	  await rename(temp, target);
46	}
47	
48	const tokenResponse = z.object({ access_token: z.string(), refresh_token: z.string().optional(), id_token: z.string().optional(), expires_in: z.number().optional(), scope: z.string().optional() });
49	async function token(body: Record<string, string>, previous?: Tokens) {
50	  const response = await fetch(`${AUTH}/oauth/token`, { method: "POST", headers: { "content-type": "application/x-www-form-urlencoded" }, body: new URLSearchParams({ ...body, resource: RESOURCE }) });
51	  const parsed = tokenResponse.safeParse(await response.json().catch(() => null));
52	  if (!response.ok || !parsed.success) throw new ChatGPTError(`ChatGPT sign-in failed (${response.status})`);
53	  const data = parsed.data;
54	  const tokens: Tokens = { accessToken: data.access_token, refreshToken: data.refresh_token ?? previous?.refreshToken ?? null,
55	    expiresAt: Date.now() + (data.expires_in ?? 3600) * 1000, scopes: data.scope ? data.scope.split(" ") : previous?.scopes ?? [] };
56	  return { tokens, idToken: data.id_token ?? null };
57	}
58	
59	// Only shown in Settings; nothing is authorized from it, so the payload is read without verifying.
60	function emailFrom(idToken: string | null) {
61	  try { return z.object({ email: z.string() }).parse(JSON.parse(Buffer.from(idToken!.split(".")[1], "base64url").toString())).email; }
62	  catch { return null; }
63	}
64	
65	/** The ChatGPT authorize URL. OpenAI only accepts a 127.0.0.1 loopback callback. */
66	export async function startSignIn(port: number) {
67	  const state = await load();
68	  const verifier = randomBytes(32).toString("base64url"), oauthState = randomUUID();
69	  const redirectUri = `http://127.0.0.1:${port}/api/ai/chatgpt/callback`;
70	  const clientId = state.account?.clientId ?? "dynamic_agent_client";
71	  const url = new URL(`${AUTH}/authorize`);
72	  url.search = new URLSearchParams({
73	    client_id: clientId, ext_agent_host_id: state.hostId, response_type: "code", redirect_uri: redirectUri, scope: SCOPE, resource: RESOURCE,
74	    state: oauthState, nonce: randomUUID(), code_challenge_method: "S256", code_challenge: createHash("sha256").update(verifier).digest("base64url"),
75	    ...(state.account ? { ...(state.account.idToken ? { id_token_hint: state.account.idToken } : {}), ...(state.account.email ? { login_hint: state.account.email } : {}) } : { agent_name_hint: "Moneo" }),
76	  }).toString();
77	  await save({ ...state, pending: { state: oauthState, verifier, redirectUri, clientId, createdAt: Date.now() } });
78	  return url.toString();
79	}
80	
81	export async function finishSignIn(query: URLSearchParams) {
82	  const state = await load();
83	  const pending = state.pending;
84	  if (!pending || query.get("state") !== pending.state || Date.now() - pending.createdAt > 600_000) throw new ChatGPTError("The sign-in expired. Try again.");
85	  await save({ ...state, pending: null });
86	  if (query.get("error")) throw new ChatGPTError(query.get("error") === "access_denied" ? "ChatGPT sign-in was cancelled." : "ChatGPT sign-in failed.");
87	  const issued = query.get("client_id");
88	  const clientId = pending.clientId === "dynamic_agent_client" ? issued : issued && issued !== pending.clientId ? null : pending.clientId;
89	  const code = query.get("code");
90	  if (!clientId || !code) throw new ChatGPTError("ChatGPT did not finish the sign-in. Try again.");
91	  const { tokens, idToken } = await token({ grant_type: "authorization_code", client_id: clientId, code, code_verifier: pending.verifier, redirect_uri: pending.redirectUri });
92	  if (!tokens.scopes.includes(PLAN_SCOPE)) throw new ChatGPTError("ChatGPT plan usage wasn't allowed, so Moneo can't use your plan. Sign in again and allow it.");
93	  await save({ ...state, pending: null, source: "chatgpt", account: { clientId, email: emailFrom(idToken), idToken, tokens } });
94	}
95	
96	export async function signOut() {
97	  const state = await load();
98	  if (state.account?.tokens.refreshToken) {
99	    // Best effort; the owner can also disconnect Moneo in ChatGPT settings.
100	    await fetch(`${AUTH}/oauth/revoke`, { method: "POST", headers: { "content-type": "application/x-www-form-urlencoded" },
101	      body: new URLSearchParams({ token: state.account.tokens.refreshToken, token_type_hint: "refresh_token", client_id: state.account.clientId }) }).catch(() => undefined);
102	  }
103	  // The registered client id stays with the host id for a later sign-in to the same account.
104	  await save({ ...state, account: null, source: state.source === "claude" ? "claude" : "api_key" });
105	}
106	
107	export async function setAiSource(source: AiSource) {
108	  await save({ ...(await load()), source });
109	}
110	
111	export async function chatgptStatus() {
112	  const state = await load().catch(() => null);
113	  return { signedIn: Boolean(state?.account), email: state?.account?.email ?? null, source: state?.source ?? "api_key" };
114	}
115	
116	let refreshing: Promise<string> | null = null;
117	/** A valid access token, refreshed near expiry. Refreshes are serialized because the refresh token rotates. */
118	export async function chatgptAccessToken(): Promise<string> {
119	  if (refreshing) return refreshing;
120	  const account = (await load()).account;
121	  if (!account) throw new ChatGPTError("Not signed in with ChatGPT");
122	  if (account.tokens.expiresAt - Date.now() > 120_000) return account.tokens.accessToken;
123	  refreshing ??= (async () => {
124	    try {
125	      // Read again inside the lock: another caller may have just stored a rotated token.
126	      const account = (await load()).account;
127	      if (!account) throw new ChatGPTError("Not signed in with ChatGPT");
128	      if (account.tokens.expiresAt - Date.now() > 120_000) return account.tokens.accessToken;
129	      if (!account.tokens.refreshToken) throw new ChatGPTError("The ChatGPT sign-in ended. Sign in again in Settings.");
130	      const { tokens, idToken } = await token({ grant_type: "refresh_token", client_id: account.clientId, refresh_token: account.tokens.refreshToken }, account.tokens);
131	      await save({ ...(await load()), account: { ...account, idToken: idToken ?? account.idToken, tokens } });
132	      return tokens.accessToken;
133	    } finally { refreshing = null; }
134	  })();
135	  return refreshing;
136	}
