138	/**
139	 * True when AI requests for plain OpenAI model ids should use the ChatGPT plan: unless the owner picked the
140	 * API key, a signed-in plan pays, including for GPT models mixed in while Claude is the main source.
141	 */
142	export async function usesChatGPT() {
143	  const status = await chatgptStatus();
144	  return status.signedIn && (status.source !== "api_key" || !(await serviceKey("openai_api_key")));
145	}
