147	// Plan usage accepts only streaming Responses calls with store: false and without sampling limits.
148	const UNSUPPORTED = ["background", "conversation", "max_output_tokens", "max_tool_calls", "metadata", "moderation", "previous_response_id", "prompt",
149	  "prompt_cache_retention", "safety_identifier", "service_tier", "temperature", "top_logprobs", "top_p", "truncation", "user"];
150	
151	/** fetch for the OpenAI provider: adds the plan token and turns a non-streaming call into a stream it reads to the end. */
152	export async function chatgptFetch(input: RequestInfo | URL, init: RequestInit = {}): Promise<Response> {
153	  const headers = new Headers(init.headers);
154	  headers.set("authorization", `Bearer ${await chatgptAccessToken()}`);
155	  const url = String(input instanceof Request ? input.url : input);
156	  if (!url.endsWith("/responses") || typeof init.body !== "string") return fetch(input, { ...init, headers });
157	  const body = JSON.parse(init.body) as Record<string, unknown>;
158	  const wantsStream = body.stream === true;
159	  for (const field of UNSUPPORTED) delete body[field];
160	  const response = await fetch(input, { ...init, headers, body: JSON.stringify({ ...body, store: false, stream: true }) });
161	  if (wantsStream || !response.ok || !response.body) return response;
162	  const final = await finalResponse(response.body);
163	  return new Response(JSON.stringify(final), { status: 200, headers: { "content-type": "application/json" } });
164	}
165	
166	/** The response object from the stream's terminal event (completed, incomplete or failed). */
167	export async function finalResponse(stream: ReadableStream<Uint8Array>) {
168	  const reader = stream.pipeThrough(new TextDecoderStream() as unknown as ReadableWritablePair<string, Uint8Array>).getReader();
169	  let buffer = "", last: unknown = null;
170	  for (;;) {
171	    const { value, done } = await reader.read();
172	    buffer += value ?? "";
173	    const lines = buffer.split(/\r?\n/);
174	    buffer = done ? "" : lines.pop()!;
175	    for (const line of lines) {
176	      if (!line.startsWith("data:")) continue;
177	      const event = (() => { try { return JSON.parse(line.slice(5)) as { type?: string; response?: unknown }; } catch { return null; } })();
178	      if (event?.response && ["response.completed", "response.incomplete", "response.failed"].includes(event.type ?? "")) last = event.response;
179	    }
180	    if (done) break;
181	  }
182	  if (!last) throw new ChatGPTError("ChatGPT ended the response early");
183	  return last;
184	}
