1	import { execFile, spawn, type ChildProcess, type SpawnOptions } from "node:child_process";
2	import { existsSync } from "node:fs";
3	import { createRequire } from "node:module";
4	import type { ToolSet } from "ai";
5	import { claudeCode, createAiSdkMcpServer, type ClaudeCodeSettings, type MessageInjector } from "ai-sdk-provider-claude-code";
