8	// Claude plan usage: requests run through Claude Code (the Claude Agent SDK's bundled binary) signed in
9	// with the owner's own claude.ai account, so they count toward that plan, never an API key. Moneo never
10	// sees or stores the Claude token; Claude Code keeps it on this computer.
11	// Docs: https://code.claude.com/docs/en/agent-sdk/overview
12	
13	export class ClaudeError extends Error {}
14	
15	/** The Claude Code binary that ships with the Agent SDK for this platform, or null when it isn't installed. */
16	export function claudeExecutable(): string | null {
17	  const require = createRequire(import.meta.url);
18	  const base = `@anthropic-ai/claude-agent-sdk-${process.platform}-${process.arch}`;
19	  // Both Linux builds can be installed; a glibc binary won't start on musl (Alpine), so pick by libc.
20	  const glibc = process.platform === "linux" && Boolean((process.report?.getReport() as { header?: { glibcVersionRuntime?: string } } | undefined)?.header?.glibcVersionRuntime);
21	  for (const name of process.platform === "linux" ? glibc ? [base, `${base}-musl`] : [`${base}-musl`, base] : [base]) {
22	    try {
23	      const file = require.resolve(/*turbopackIgnore: true*/ `${name}/claude${process.platform === "win32" ? ".exe" : ""}`);
24	      if (existsSync(/*turbopackIgnore: true*/ file)) return file;
25	    } catch { /* try the next one */ }
26	  }
27	  return null;
28	}
