30	// Any of these would make Claude Code bill an API key or a cloud account instead of the plan.
31	const PAID_ROUTES = ["ANTHROPIC_API_KEY", "ANTHROPIC_AUTH_TOKEN", "ANTHROPIC_BASE_URL", "CLAUDE_CODE_USE_BEDROCK", "CLAUDE_CODE_USE_VERTEX", "CLAUDE_CODE_USE_FOUNDRY"];
32	/**
33	 * The environment for Claude Code: this process's, with everything that routes requests away from the plan
34	 * set to undefined. Undefined, not left out: the adapter merges its own copy of ANTHROPIC_* and CLAUDE_*
35	 * variables underneath, so only an explicit undefined removes them (Node skips undefined when spawning).
36	 */
37	export function claudeEnv(env: Record<string, string | undefined> = process.env) {
38	  return { ...env, ...Object.fromEntries(PAID_ROUTES.map(key => [key, undefined])) } as NodeJS.ProcessEnv;
39	}
40	
41	const statusSchema = z.object({ loggedIn: z.boolean(), authMethod: z.string().nullish(), email: z.string().nullish(), subscriptionType: z.string().nullish() });
42	export type ClaudeAccount = { installed: boolean; signedIn: boolean; email: string | null; plan: string | null; problem: string | null };
43	
44	/** What `claude auth status` says, read as plan sign-in only: an API-key or Console login doesn't count. */
45	export function accountFrom(output: string): ClaudeAccount {
46	  const parsed = statusSchema.safeParse((() => { try { return JSON.parse(output); } catch { return null; } })());
47	  if (!parsed.success) return { installed: true, signedIn: false, email: null, plan: null, problem: "Claude Code's sign-in status could not be read." };
48	  const { loggedIn, authMethod, email, subscriptionType } = parsed.data;
49	  const plan = loggedIn && authMethod === "claude.ai";
50	  return { installed: true, signedIn: plan, email: plan ? email ?? null : null, plan: plan ? subscriptionType ?? null : null,
51	    problem: loggedIn && !plan ? "Claude Code is signed in with an API key or Console account, not a Claude plan. Sign in with Claude to use your plan." : null };
52	}
53	
54	const cache = globalThis as typeof globalThis & { moneoClaudeAccount?: { at: number; value: Promise<ClaudeAccount> } };
55	/** The Claude account Claude Code is signed in with, read at most every 30 seconds. */
56	export function claudeAccount(): Promise<ClaudeAccount> {
57	  if (cache.moneoClaudeAccount && Date.now() - cache.moneoClaudeAccount.at < 30_000) return cache.moneoClaudeAccount.value;
58	  const executable = claudeExecutable();
59	  const value = executable ? new Promise<ClaudeAccount>(resolve => execFile(/*turbopackIgnore: true*/ executable, ["auth", "status", "--json"], { env: claudeEnv(), timeout: 20_000, windowsHide: true },
60	    (error, stdout) => resolve(stdout.trim() ? accountFrom(stdout) : { installed: true, signedIn: false, email: null, plan: null, problem: error ? "Claude Code did not answer. Try again." : null })))
61	    : Promise.resolve({ installed: false, signedIn: false, email: null, plan: null, problem: "Claude Code is missing from this install. Run npm ci, then restart Moneo." });
62	  cache.moneoClaudeAccount = { at: Date.now(), value };
63	  return value;
64	}
65	export const forgetClaudeAccount = () => { delete cache.moneoClaudeAccount; };
66	
67	// Sign-in runs Claude Code's own `claude auth login`: it opens the browser on this computer and, when the
68	// page shows a code instead of finishing on its own, reads that code from its input.
69	type SignIn = { process: ChildProcess; url: string | null; output: string; done: boolean; error: string | null };
70	const login = globalThis as typeof globalThis & { moneoClaudeSignIn?: SignIn };
71	const AUTHORIZE_URL = /https:\/\/\S+\/oauth\/authorize\?\S+/;
72	
73	export function claudeSignInState() {
74	  const current = login.moneoClaudeSignIn;
75	  return current ? { running: !current.done, url: current.url, error: current.error } : { running: false, url: null, error: null };
76	}
77	
78	/** Starts Claude Code's sign-in and waits briefly for its sign-in link. */
79	export async function startClaudeSignIn(spawnProcess: (command: string, args: string[], options: SpawnOptions) => ChildProcess = spawn) {
80	  const executable = claudeExecutable();
81	  if (!executable) throw new ClaudeError("Claude Code is missing from this install. Run npm ci, then restart Moneo.");
82	  cancelClaudeSignIn();
83	  const child = spawnProcess(/*turbopackIgnore: true*/ executable, ["auth", "login", "--claudeai"], { env: claudeEnv(), stdio: ["pipe", "pipe", "pipe"], windowsHide: true });
84	  const state: SignIn = { process: child, url: null, output: "", done: false, error: null };
85	  login.moneoClaudeSignIn = state;
86	  const read = (chunk: Buffer) => {
87	    state.output = (state.output + chunk.toString()).slice(-4000);
88	    state.url ??= state.output.match(AUTHORIZE_URL)?.[0] ?? null;
89	  };
90	  child.stdout?.on("data", read);

