14	export type InvestigationEntities = Record<"accounts" | "categories" | "merchants", { id: string; name: string }[]> & { labels?: { tags: string[]; events: string[] } };
15	const entityKeys = ["accounts", "categories", "merchants"] as const;
16	const normalized = (value: string) => value.normalize("NFKC").trim().toLocaleLowerCase("en");
17	
18	/** Resolve only owned entities; ambiguity is a correction request, never a guessed ID. */
19	export function resolveInvestigation(input: unknown, entities: InvestigationEntities): InvestigationSpec {
20	  const spec = investigationSchema.parse(input);
21	  for (const key of entityKeys) {
22	    const filter = spec[key];
23	    if (!filter) continue;
24	    for (const operation of ["include", "exclude"] as const) {
25	      filter[operation] = filter[operation]?.map(ref => {
26	        const matches = entities[key].filter(e => "id" in ref ? e.id === ref.id : normalized(e.name) === normalized(ref.name));
27	        if (!matches.length) throw new Error(`Unknown owned ${key}: ${"id" in ref ? ref.id : ref.name}`);
28	        if (matches.length !== 1) throw new Error(`Ambiguous ${key}: ${"name" in ref ? ref.name : ref.id}; choose an ID from the owned entity list`);
29	        return { id: matches[0].id };
30	      });
31	    }
32	  }
33	  for (const key of ["tags", "events"] as const) {
34	    const filter = spec[key], labels = entities.labels?.[key];
35	    if (!filter || !labels) continue;
36	    for (const operation of ["include", "exclude"] as const) filter[operation] = filter[operation]?.map(value => {
37	      const owned = labels.filter(label => normalized(label) === normalized(value)).sort()[0];
38	      if (!owned) throw new Error(`Unknown owned ${key}: ${value}`);
39	      // These entities are stored as text labels, not UUIDs. Use the existing stable label.
40	      return owned;
41	    });
42	  }
43	  return spec;
44	}
