46	// Sort object keys and set-valued query fields so equivalent requests share identities.
47	function canonical(value: unknown): unknown {
48	  if (Array.isArray(value)) return value.map(canonical);
49	  if (value && typeof value === "object") return Object.fromEntries(Object.entries(value).sort(([a], [b]) => a.localeCompare(b)).map(([k, v]) => [k, canonical(v)]));
50	  return value;
51	}
52	export const investigationIdentity = (value: unknown) => createHash("sha256").update(JSON.stringify(canonical(value))).digest("hex");
53	const abs = (value: bigint) => value < 0n ? -value : value;
54	const compare = (a: bigint, b: bigint) => a < b ? -1 : a > b ? 1 : 0;
