1	import type { SupabaseClient } from "@supabase/supabase-js";
2	import { z } from "zod";
3	import { requireWorkspace } from "@/lib/auth";
4	import { allPages } from "@/lib/all-pages";
5	import { perClient } from "@/lib/per-client";
6	import { investigate, investigationIdentity, investigationSchema, resolveInvestigation, type InvestigationEntities, type InvestigationRow, type InvestigationSpec } from "./investigation";
7	import { buildSourceCoverage, loadSourceCoverageMetadata } from "./source-coverage";
8	
9	type Context = { supabase: SupabaseClient; workspace: { id: string } };
10	const MAX_ROWS = 100_000;
11	
12	/** A resource bound is an explicit error, never a silently incomplete result. */
13	// `query` builds a fresh ordered query for each page; `count` goes to its select.
14	async function allRows<T>(query: (count?: "exact") => { range(from: number, to: number): PromiseLike<{ data: unknown[] | null; error: unknown; count?: number | null }> }): Promise<T[]> {
15	  const result = await allPages<T>((from, to, count) => query(count).range(from, to));
16	  if (result.length > MAX_ROWS) throw new Error("Investigation exceeds 100,000 records; narrow its dates or filters");
17	  return result;
18	}
19	const counted = (count?: "exact") => count ? { count } : undefined;
20	export async function loadInvestigationEntities(context?: Context): Promise<InvestigationEntities> {
21	  const { supabase, workspace } = context ?? await requireWorkspace();
22	  const [accounts, categories, merchants, labels] = await Promise.all([
23	    ...["accounts", "categories", "merchants"].map(table => allRows<{ id: string; name: string }>(count => supabase.from(table).select(table === "accounts" ? "id, name, version" : "id, name", counted(count)).eq("workspace_id", workspace.id).order("id"))),
24	    allRows<{ tags: string[]; event_name: string | null }>(count => supabase.from("transactions").select("tags, event_name", counted(count)).eq("workspace_id", workspace.id).order("id")),
25	  ]) as [{ id: string; name: string }[], { id: string; name: string }[], { id: string; name: string }[], { tags: string[]; event_name: string | null }[]];
26	  return { accounts, categories, merchants, labels: { tags: [...new Set(labels.flatMap(r => r.tags ?? []))].sort(), events: [...new Set(labels.flatMap(r => r.event_name ? [r.event_name] : []))].sort() } };
27	}
28	type LedgerRow = {
29	  id: string; parent_transaction_id: string; account_id: string; category_id: string | null; merchant_id: string | null;
30	  posted_on: string; amount_minor: string; currency_code: string; status: InvestigationRow["status"]; kind: InvestigationRow["kind"];
31	  tags: string[]; event_name: string | null; review_reasons: string[]; version: number; description: string; refund_of_id: string | null;
32	};
33	// Investigations in one request (an artifact's saved queries) share these whole-workspace reads.
34	const sourcesFor = perClient((supabase: SupabaseClient, workspaceId: string) =>
35	  allRows<Source>(count => supabase.from("source_transactions").select("id, import_id, status, review_reasons, normalized_row, fee_evidence, imports(run_version, status, undone_at), transaction_sources(transaction_id)", counted(count)).eq("workspace_id", workspaceId).order("id")));
36	const ratesFor = perClient((supabase: SupabaseClient, workspaceId: string) =>
37	  allRows<{ id: string; from_currency: string; to_currency: string; rate_text: string; rate_date: string; source: string }>(count => supabase.from("fx_rates").select("id, from_currency, to_currency, rate_text, rate_date, source", counted(count)).eq("workspace_id", workspaceId).order("id")));
38	type Source = { id: string; import_id: string; status: string; review_reasons: string[]; normalized_row: unknown; fee_evidence: unknown;
39	  imports: { run_version: number; status: string; undone_at: string | null } | null; transaction_sources: { transaction_id: string }[] | { transaction_id: string } | null };
40	
41	async function loadRows(context: Context, spec: InvestigationSpec, includeAll = false, canReadImports = true, withSources = canReadImports) {
42	  const { supabase, workspace } = context;
43	  const from = [spec.period.from, spec.comparison?.from].filter((v): v is string => Boolean(v)).sort()[0];
44	  const to = [spec.period.to, spec.comparison?.to].filter((v): v is string => Boolean(v)).sort().at(-1)!;
45	  const ledger = (count?: "exact") => {
46	    const query = supabase.from("effective_transactions")
47	      .select("id, parent_transaction_id, account_id, category_id, merchant_id, posted_on, amount_minor::text, currency_code, status, kind, tags, event_name, review_reasons, version, description, refund_of_id", counted(count))
48	      .eq("workspace_id", workspace.id);
49	    return (includeAll ? query : query.gte("posted_on", from).lte("posted_on", to)).order("id");
50	  };
51	  const [effective, sources] = await Promise.all([
52	    allRows<LedgerRow>(ledger),
53	    withSources ? sourcesFor(supabase, workspace.id) : [],
54	  ]);
55	  const byParent = new Map<string, unknown[]>();
56	  for (const source of sources) for (const link of Array.isArray(source.transaction_sources) ? source.transaction_sources : source.transaction_sources ? [source.transaction_sources] : []) {
57	    const values = byParent.get(link.transaction_id) ?? [];
58	    values.push({ id: source.id, importId: source.import_id, link: `/import/${encodeURIComponent(source.import_id)}/review`, status: source.status, import: source.imports,
59	      identity: investigationIdentity({ normalized: source.normalized_row, fees: source.fee_evidence, reviewReasons: source.review_reasons }) });
60	    byParent.set(link.transaction_id, values);
61	  }
62	  const rows: InvestigationRow[] = effective.map(r => ({ id: r.id, parentId: r.parent_transaction_id, accountId: r.account_id,
63	    categoryId: r.category_id, merchantId: r.merchant_id, date: r.posted_on, amountMinor: r.amount_minor, currency: r.currency_code,
64	    status: r.status, kind: r.kind, tags: r.tags ?? [], event: r.event_name, reviewReasons: r.review_reasons ?? [], version: r.version,
65	    description: r.description, refundOfId: r.refund_of_id, sourceVersions: byParent.get(r.parent_transaction_id) ?? [] }));
66	  // Refunds inherit the verified original category when their own category is unset.
67	  const refundIds = [...new Set(rows.filter(r => r.kind === "refund" && !r.categoryId && r.refundOfId).map(r => r.refundOfId!))];
68	  for (let offset = 0; offset < refundIds.length; offset += 100) {
69	    const original = await supabase.from("transactions").select("id, category_id, version").eq("workspace_id", workspace.id).in("id", refundIds.slice(offset, offset + 100));
70	    if (original.error) throw original.error;
71	    for (const row of rows) if (row.kind === "refund" && !row.categoryId && row.refundOfId) {
72	      const parent = original.data?.find(r => r.id === row.refundOfId);
73	      if (parent) { row.categoryId = parent.category_id; row.sourceVersions = { sources: row.sourceVersions, refundOriginal: parent }; }
74	    }
75	  }
76	  return rows;
77	}
78	
79	/**
80	 * Internal dataset is retained in full for evidence receipts; outward supporting access is paginated.
81	 * `entities` lets a caller that already reads them (the Investigations page) share that read.
82	 * `sourceVersions: false` skips each record's import sources, for readers that never show them (chat, artifacts).
83	 */
84	export async function loadInvestigationDataset(input: unknown, context?: Context, options: { canReadImports?: boolean; includeAll?: boolean; entities?: Promise<InvestigationEntities>; sourceVersions?: boolean } = {}) {
85	  const ctx = context ?? await requireWorkspace();
86	  const entities = await (options.entities ?? loadInvestigationEntities(ctx));
87	  const spec = resolveInvestigation(input, entities);
88	  const canReadImports = options.canReadImports ?? true;
89	  const [rows, metadata, rates] = await Promise.all([loadRows(ctx, spec, options.includeAll ?? false, canReadImports, canReadImports && (options.sourceVersions ?? true)), loadSourceCoverageMetadata(ctx.supabase, ctx.workspace.id, canReadImports),
90	    spec.currencyPolicy.mode === "base" ? ratesFor(ctx.supabase, ctx.workspace.id) : []]);
91	  const accountIds = spec.accounts?.include?.flatMap(ref => "id" in ref ? [ref.id] : []);
92	  const scope = { ...(accountIds?.length ? { accountIds } : {}), ...(spec.currencyPolicy.mode === "original" && spec.currencyPolicy.currencies?.length === 1 ? { currencyCode: spec.currencyPolicy.currencies[0] } : {}) };
93	  const effective = rows.map(r => ({ account_id: r.accountId, posted_on: r.date, currency_code: r.currency, status: r.status, kind: r.kind, review_reasons: r.reviewReasons }));
94	  const sourceCoverage = { current: buildSourceCoverage({ ...spec.period, ...scope }, effective, metadata?.imports, metadata?.sources),
95	    comparison: spec.comparison ? buildSourceCoverage({ ...spec.comparison, ...scope }, effective, metadata?.imports, metadata?.sources) : null,
96	    attribution: "Period/account source coverage spans all categories; query filters and eligibility are reported separately." };
97	  return { spec, rows, context: { workspaceId: ctx.workspace.id, capturedAt: new Date().toISOString(), sourceCoverage, entities,
98	    rates: rates.map(r => ({ id: r.id, fromCurrency: r.from_currency, toCurrency: r.to_currency, rateText: r.rate_text, rateDate: r.rate_date, source: r.source })) },
99	    sourceRevision: investigationIdentity({ rows, metadata, rates, entities }) };
100	}
101	export async function runInvestigation(input: unknown, context?: Context, options: { canReadImports?: boolean; entities?: Promise<InvestigationEntities>; sourceVersions?: boolean } = {}) {
102	  const data = await loadInvestigationDataset(input, context, options);
103	  const result = investigate(data.spec, data.rows, data.context);
104	  return { ...result, sourceRevision: data.sourceRevision,
105	    link: `/money/investigations?${new URLSearchParams({ query: JSON.stringify({ ...data.spec, page: { size: 25, period: "both" } }) })}` };
106	}
107	
108	const minor = z.string().regex(/^-?\d{1,19}$/).refine(v => BigInt(v) >= -(2n ** 63n) && BigInt(v) <= 2n ** 63n - 1n, "Amount exceeds bigint range");
109	export const investigationScenarioSchema = z.object({ query: investigationSchema, overrides: z.array(z.object({
110	  id: z.uuid(), amountMinor: minor.optional(), date: z.iso.date().optional(), categoryId: z.uuid().nullable().optional(),
111	}).strict().refine(o => o.amountMinor !== undefined || o.date !== undefined || o.categoryId !== undefined, "Provide an override")).min(1).max(100) }).strict().refine(v => new Set(v.overrides.map(o => o.id)).size === v.overrides.length, "Duplicate override");
112	
113	export async function evaluateInvestigationScenario(input: unknown, context?: Context, options: { canReadImports?: boolean } = {}) {
114	  const args = investigationScenarioSchema.parse(input);
115	  const ctx = context ?? await requireWorkspace();
116	  const entities = await loadInvestigationEntities(ctx);
117	  const spec = resolveInvestigation(args.query, entities);
118	  const dataset = await loadInvestigationDataset(spec, ctx, { ...options, includeAll: true });
119	  const rows = dataset.rows;
120	  for (const override of args.overrides) {
121	    if (!rows.some(r => r.id === override.id)) throw new Error("Unknown owned effective transaction in scenario");
122	    if (override.categoryId && !entities.categories.some(c => c.id === override.categoryId)) throw new Error("Unknown owned category in scenario");
123	  }
124	  const evidence = dataset.context;
125	  const hypothetical = rows.map(row => {
126	    const override = args.overrides.find(o => o.id === row.id);
127	    return override ? { ...row, ...override } : row;
128	  });
129	  return { version: 1, canonicalMutations: false, hypothetical: investigate(spec, hypothetical, evidence), baseline: investigate(spec, rows, evidence),
130	    overrides: args.overrides, limitation: "Read-only effective-row overrides. No canonical edits, bank balances, recurring assumptions or source records are changed." };
131	}
132	
133	export const investigationDetailSchema = z.object({ kind: z.enum(["transaction", "recurring"]), id: z.uuid(),
134	  offset: z.number().int().min(0).max(MAX_ROWS).default(0), size: z.number().int().min(1).max(100).default(25) }).strict();
135	
136	export async function investigationDetail(input: unknown, context?: Context, options: { canReadImports?: boolean } = {}) {
137	  const args = investigationDetailSchema.parse(input);
138	  const ctx = context ?? await requireWorkspace();
139	  if (args.kind === "transaction") {
140	    const result = await ctx.supabase.from("transactions").select("id, account_id, posted_on, description, amount_minor::text, currency_code, status, kind, category_id, merchant_id, tags, event_name, review_reasons, version, transfer_id, refund_of_id")
141	      .eq("workspace_id", ctx.workspace.id).eq("id", args.id).maybeSingle();
142	    if (result.error) throw result.error;
143	    if (!result.data) throw new Error("Unknown owned transaction");
144	    const spec = investigationSchema.parse({ version: 1, period: { from: result.data.posted_on, to: result.data.posted_on } });
145	    const all = (await loadRows(ctx, spec, false, options.canReadImports ?? true)).filter(r => r.parentId === args.id);
146	    return { kind: args.kind, transaction: result.data, link: `/money/transactions?transaction=${args.id}`,
147	      effectiveRows: all.slice(args.offset, args.offset + args.size), total: all.length, nextOffset: args.offset + args.size < all.length ? args.offset + args.size : null };
148	  }
149	  const result = await ctx.supabase.from("recurring_series").select("id, account_id, label, cadence, currency_code, amount_min_minor::text, amount_max_minor::text, occurrences, confidence, status, assumption_id, evidence_invalidated")
150	    .eq("workspace_id", ctx.workspace.id).eq("id", args.id).maybeSingle();
151	  if (result.error) throw result.error;
152	  if (!result.data) throw new Error("Unknown owned recurring series");
153	  const links = await allRows<{ transaction_id: string }>(count => ctx.supabase.from("recurring_series_transactions").select("transaction_id", counted(count)).eq("workspace_id", ctx.workspace.id).eq("series_id", args.id).order("transaction_id"));
154	  const ids = links.slice(args.offset, args.offset + args.size).map(l => l.transaction_id);
155	  const transactions = ids.length ? await ctx.supabase.from("transactions").select("id, posted_on, description, amount_minor::text, currency_code, status, kind, review_reasons, version")
156	    .eq("workspace_id", ctx.workspace.id).in("id", ids).order("posted_on").order("id") : { data: [], error: null };
157	  if (transactions.error) throw transactions.error;
158	  return { kind: args.kind, series: result.data, link: "/money/recurring", total: links.length,
159	    transactions: transactions.data.map(r => ({ ...r, link: `/money/transactions?transaction=${r.id}` })), nextOffset: args.offset + args.size < links.length ? args.offset + args.size : null };
160	}
161

