92	  for (const posting of report.postings) {
93	    if (posting.reportingAmountMinor === null || !posting.rate || !posting.rounding) {
94	      for (const child of posting.sourcePostings) allocated.set(child.id, null);
95	      continue;
96	    }
97	    const denominator = BigInt(posting.rounding.scaledDenominator);
98	    const multiplier = BigInt(posting.rate.numerator) * 10n ** BigInt(minorDigits(spec.currencyPolicy.currency));
99	    const shares = posting.sourcePostings.map(child => {
100	      const scaled = BigInt(child.originalAmountMinor) * multiplier;
101	      let floor = scaled / denominator, remainder = scaled % denominator;
102	      if (remainder < 0n) { floor--; remainder += denominator; }
103	      return { id: child.id, floor, remainder };
104	    });
105	    let remaining = BigInt(posting.reportingAmountMinor) - shares.reduce((sum, share) => sum + share.floor, 0n);
106	    for (const share of shares.sort((a, b) => compare(b.remainder, a.remainder) || a.id.localeCompare(b.id))) {
107	      if (remaining > 0n) { share.floor++; remaining--; }
108	      allocated.set(share.id, share.floor.toString());
109	    }
110	    if (remaining !== 0n) throw new Error("Inconsistent canonical reporting allocation");
111	  }
112	  return { report: { ...report, allocationPolicy: "largest-remainder of exact signed component quotas; canonical rounded amount conserved; ties by effective ID" }, allocated };
113	}
