115	/** All effective records are loaded before totals; pagination applies solely to support. No financial writes. */
116	export function investigate(input: unknown, rows: InvestigationRow[], context: InvestigationContext, options: { retainSupport?: boolean } = {}) {
117	  const spec = investigationSchema.parse(input);
118	  const { page, ...meaning } = spec;
119	  const reporting = allocatedReporting(rows, spec, context.rates ?? []);
120	  const queryId = investigationIdentity({ workspaceId: context.workspaceId, ...meaning });
121	  const evidenceId = investigationIdentity({ queryId, rows: [...rows].sort((a, b) => a.id.localeCompare(b.id)), sourceCoverage: context.sourceCoverage ?? null, reporting: reporting?.report ?? null });
122	  const excluded = { outsidePeriod: 0, filtersExcluded: 0, statusExcluded: 0, pendingExcluded: 0, postedExcluded: 0, kindExcluded: 0, transferExcluded: 0, classificationExcluded: 0, currencyExcluded: 0 };
123	  const selected: { row: InvestigationRow; current: boolean; comparison: boolean; key: string }[] = [];
124	  const groups = new Map<string, { key: string; dimensions: ReturnType<typeof investigationGroup>; currency: string; current: bigint; comparison: bigint; currentCount: number; comparisonCount: number; supportCount: number; missingCurrent: number; missingComparison: number }>();
125	  let unresolvedIncluded = 0;
126	  let missingConversionRows = 0;
127	  for (const row of rows) {
128	    const current = row.date >= spec.period.from && row.date <= spec.period.to;
129	    const comparison = Boolean(spec.comparison && row.date >= spec.comparison.from && row.date <= spec.comparison.to);
130	    if (!current && !comparison) { excluded.outsidePeriod++; continue; }
131	    if (!entityMatches(spec.accounts, row.accountId) || !entityMatches(spec.categories, row.categoryId) || !entityMatches(spec.merchants, row.merchantId) || !labelsMatch(spec.tags, row.tags) || !labelsMatch(spec.events, row.event ? [row.event] : [])) { excluded.filtersExcluded++; continue; }
132	    if (!spec.statuses.includes(row.status)) { excluded.statusExcluded++; if (row.status === "pending") excluded.pendingExcluded++; else excluded.postedExcluded++; continue; }
133	    if (!spec.kinds.includes(row.kind)) { excluded.kindExcluded++; if (row.kind === "transfer") excluded.transferExcluded++; continue; }
134	    if ((spec.classifications === "resolved" && row.reviewReasons.length) || (spec.classifications === "unresolved" && !row.reviewReasons.length)) { excluded.classificationExcluded++; continue; }
135	    if (spec.currencyPolicy.mode === "original" && spec.currencyPolicy.currencies && !spec.currencyPolicy.currencies.includes(row.currency)) { excluded.currencyExcluded++; continue; }
136	    if (row.reviewReasons.length) unresolvedIncluded++;
137	    const dimensions = investigationGroup(row, spec.groupBy);
138	    const currency = spec.currencyPolicy.mode === "base" ? spec.currencyPolicy.currency : row.currency;
139	    const key = JSON.stringify([currency, dimensions]);
140	    const group = groups.get(key) ?? { key, dimensions, currency, current: 0n, comparison: 0n, currentCount: 0, comparisonCount: 0, supportCount: 0, missingCurrent: 0, missingComparison: 0 };
141	    const converted = reporting?.allocated.get(row.id);
142	    const missing = reporting !== null && converted == null && spec.metric !== "count";
143	    if (missing) { missingConversionRows++; if (current) group.missingCurrent++; if (comparison) group.missingComparison++; }
144	    const value = missing ? 0n : metricValue(reporting && converted != null ? { ...row, amountMinor: converted } : row, spec.metric);
145	    if (current) { group.current += value; group.currentCount++; }
146	    if (comparison) { group.comparison += value; group.comparisonCount++; }
147	    group.supportCount++;
148	    groups.set(key, group);
149	    selected.push({ row, current, comparison, key });
150	  }
151	  const sorted = [...groups.values()].sort((a, b) => {
152	    const deltaA = a.current - a.comparison, deltaB = b.current - b.comparison;
153	    const amountOrder = spec.sort === "delta-desc" ? compare(deltaB, deltaA) : spec.sort === "delta-asc" ? compare(deltaA, deltaB) : spec.sort === "absolute-delta-desc" ? compare(abs(deltaB), abs(deltaA)) : spec.sort === "current-desc" ? compare(b.current, a.current) : spec.sort === "current-asc" ? compare(a.current, b.current) : 0;
154	    // No ranking across currencies: exact minor units are comparable only within a currency.
155	    return a.currency.localeCompare(b.currency) || amountOrder || a.key.localeCompare(b.key);
156	  });
157	  if (page.groupKey && !groups.has(page.groupKey)) throw new Error("Unknown investigation group");
158	  const supporting = selected.filter(s => (!page.groupKey || s.key === page.groupKey) && (page.period === "both" || s[page.period])).sort((a, b) => b.row.date.localeCompare(a.row.date) || a.row.id.localeCompare(b.row.id));
159	  let offset = 0;
160	  if (page.cursor) {
161	    let cursor: unknown;
162	    try { cursor = JSON.parse(Buffer.from(page.cursor, "base64url").toString("utf8")); } catch { throw new Error("Invalid investigation cursor"); }
163	    const parsed = z.object({ evidenceId: z.string(), offset: z.number().int().nonnegative(), scope: z.string() }).strict().parse(cursor);
164	    if (parsed.evidenceId !== evidenceId || parsed.scope !== investigationIdentity({ groupKey: page.groupKey ?? null, period: page.period })) throw new Error("Investigation evidence or supporting scope changed; restart pagination");
165	    offset = parsed.offset;
166	  }
167	  const nextOffset = offset + page.size;
168	  const record = ({ row, current, comparison, key }: typeof selected[number]) => ({ ...row, current, comparison, groupKey: key, reportingAmountMinor: reporting ? reporting.allocated.get(row.id) ?? null : null, link: `/money/transactions?transaction=${encodeURIComponent(row.parentId)}` });
169	  const selectedIds = new Set(selected.map(item => item.row.id));
170	  const selectedParents = new Set(selected.map(item => item.row.parentId));
171	  return {
172	    version: 1 as const, queryId, evidenceId, evidence: { mode: "live" as const, capturedAt: context.capturedAt, datedSnapshot: false },
173	    interpretedFilters: meaning, metric: spec.metric, currencyPolicy: spec.currencyPolicy,
174	    reporting: reporting ? { currency: spec.currencyPolicy.mode === "base" ? spec.currencyPolicy.currency : null,
175	      policy: reporting.report.policy, allocationPolicy: reporting.report.allocationPolicy,
176	      postings: reporting.report.postings.filter(p => p.sourcePostings.some(s => selectedIds.has(s.id))),
177	      exclusions: reporting.report.exclusions.filter(exclusion => selectedParents.has(exclusion.id) || selectedIds.has(exclusion.id)),
178	      basis: "Canonical conversion before entity filters; groups contain only the selected allocated components." } : null,
179	    groups: sorted.map(g => ({ key: g.key, dimensions: g.dimensions, currency: g.currency, currentMinor: g.missingCurrent ? null : g.current.toString(), comparisonMinor: spec.comparison && !g.missingComparison ? g.comparison.toString() : null, deltaMinor: spec.comparison && !g.missingCurrent && !g.missingComparison ? (g.current - g.comparison).toString() : null, availableCurrentMinor: g.current.toString(), availableComparisonMinor: g.comparison.toString(), currentCount: g.currentCount, comparisonCount: g.comparisonCount, supportCount: g.supportCount })),
180	    coverage: { ...excluded, effectiveRowsObserved: rows.length, includedRows: selected.length, unresolvedIncluded, missingConversionRows, partial: excluded.classificationExcluded > 0 || unresolvedIncluded > 0 || missingConversionRows > 0, sourceCoverage: context.sourceCoverage ?? { status: "unknown", statementCompleteness: "unknown" }, ...(excluded.classificationExcluded > 0 || unresolvedIncluded > 0 || missingConversionRows > 0 ? { limitation: "Some rows are excluded (classification review or missing FX rate); totals cover included rows only." } : {}) },
181	    records: { total: supporting.length, items: supporting.slice(offset, nextOffset).map(record), nextCursor: nextOffset < supporting.length ? Buffer.from(JSON.stringify({ evidenceId, offset: nextOffset, scope: investigationIdentity({ groupKey: page.groupKey ?? null, period: page.period }) })).toString("base64url") : null },
182	    ...(options.retainSupport ? { retainedRecords: selected.map(record) } : {}),
183	  };
184	}
