1	import { minorDigits } from "./fx";
2	
3	function exactMinor(value: bigint | string | number): bigint {
4	  if (typeof value === "number" && !Number.isSafeInteger(value)) throw new Error("Unsafe minor amount");
5	  return BigInt(value);
6	}
7	
8	export function formatMoney(amountMinor: bigint | string | number, currencyCode: string, locale?: string): string {
9	  const value = exactMinor(amountMinor);
10	  const abs = value < 0n ? -value : value;
11	  const digits = minorDigits(currencyCode);
12	  const divisor = 10n ** BigInt(digits);
13	  const whole = abs / divisor;
14	  if (locale) {
15	    const integer = new Intl.NumberFormat(locale, { maximumFractionDigits: 0 }).format(whole);
16	    const decimal = new Intl.NumberFormat(locale).formatToParts(1.1).find(part => part.type === "decimal")?.value ?? ".";
17	    const fraction = new Intl.NumberFormat(locale, { useGrouping: false, minimumIntegerDigits: Math.max(1, digits), maximumFractionDigits: 0 }).format(abs % divisor);
18	    return `${value < 0n ? "-" : ""}${currencyCode} ${integer}${digits ? decimal + fraction : ""}`;
19	  }
20	  if (digits === 0) {
21	    return `${value < 0n ? "-" : ""}${currencyCode} ${whole}`;
22	  }
23	  const fraction = (abs % divisor).toString().padStart(digits, "0");
24	  return `${value < 0n ? "-" : ""}${currencyCode} ${whole}.${fraction}`;
25	}
26	
27	const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
28	
29	// Turns internal missing-input keys (e.g. "balance:<id>:missing") into short,
30	// deduplicated sentences. Unknown keys pass through unchanged.
31	export function describeMissingInputs(keys: string[], names: Map<string, string> = new Map()): string[] {
32	  const label = (ref: string) => names.get(ref) ?? (uuid.test(ref) ? "An account" : ref);
33	  const describe = (key: string): string => {
34	    const named = /^(.+) for (.+)$/.exec(key);
35	    if (named) return `${describe(named[1]).replace(/^(An account|A balance)/, named[2])}`;
36	    const [kind, ...rest] = key.split(":");
37	    if (kind === "balance" || kind === "available-balance") return !rest[1] || rest[1] === "missing" ? `${label(rest[0])} needs a current balance` : rest[1] === "stale" ? `${label(rest[0])} has an out-of-date balance` : `${label(rest[0])} balance is ${rest.slice(1).join(":")}`;
38	    if (kind === "rate") return `An account needs a ${rest.join(":").replace("->", " to ")} exchange rate`;
39	    if (kind === "currency") return `Currency ${rest[0]} is not supported`;
40	    if (kind === "fx") return rest.length > 1 && rest[0] !== "scenario" ? `${label(rest[1])} needs an exchange rate` : "An exchange rate is missing";
41	    if (kind === "valuation") return `${names.get(rest[0]) ?? "A valuation"} is dated in the future`;
42	    if (kind === "debt") return `A debt ${rest.slice(1).join(":") || "needs repayment terms"}`;
43	    if (kind === "occurrence") return `${rest[0]} on ${rest[1]}: evidence changed, review the association`;
44	    return key;
45	  };
46	  return [...new Set(keys.map(describe))];
47	}
48	
49	/** The note beside a total that counts older valuations: how many, which, and from when. */
50	export function describeOutdated(items: { name: string; asOf: string }[], date: (value: string) => string = value => value): string {
51	  const dates = [...new Set(items.map(item => item.asOf))].sort().reverse();
52	  const groups = dates.map(asOf => `${items.filter(item => item.asOf === asOf).map(item => item.name).join(", ")} (${date(asOf)})`);
53	  return `${items.length} ${items.length === 1 ? "valuation is not from today and uses its" : "valuations are not from today and use their"} last known value: ${groups.join("; ")}`;
54	}
55	
56	export function formatInputAmount(amountMinor: bigint | string | number, currencyCode: string): string {
57	  const value = exactMinor(amountMinor);
58	  const abs = value < 0n ? -value : value;
59	  const digits = minorDigits(currencyCode);
60	  const divisor = 10n ** BigInt(digits);
61	  const whole = abs / divisor;
62	  if (digits === 0) {
63	    return `${value < 0n ? "-" : ""}${whole}`;
64	  }
65	  const fraction = (abs % divisor).toString().padStart(digits, "0");
66	  return `${value < 0n ? "-" : ""}${whole}.${fraction}`;
67	}
