import { minorDigits } from "./fx";

function exactMinor(value: bigint | string | number): bigint {
  if (typeof value === "number" && !Number.isSafeInteger(value)) throw new Error("Unsafe minor amount");
  return BigInt(value);
}

export function formatMoney(amountMinor: bigint | string | number, currencyCode: string, locale?: string): string {
  const value = exactMinor(amountMinor);
  const abs = value < 0n ? -value : value;
  const digits = minorDigits(currencyCode);
  const divisor = 10n ** BigInt(digits);
  const whole = abs / divisor;
  if (locale) {
    const integer = new Intl.NumberFormat(locale, { maximumFractionDigits: 0 }).format(whole);
    const decimal = new Intl.NumberFormat(locale).formatToParts(1.1).find(part => part.type === "decimal")?.value ?? ".";
    const fraction = new Intl.NumberFormat(locale, { useGrouping: false, minimumIntegerDigits: Math.max(1, digits), maximumFractionDigits: 0 }).format(abs % divisor);
    return `${value < 0n ? "-" : ""}${currencyCode} ${integer}${digits ? decimal + fraction : ""}`;
  }
  if (digits === 0) {
    return `${value < 0n ? "-" : ""}${currencyCode} ${whole}`;
  }
  const fraction = (abs % divisor).toString().padStart(digits, "0");
  return `${value < 0n ? "-" : ""}${currencyCode} ${whole}.${fraction}`;
}

const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

// Turns internal missing-input keys (e.g. "balance:<id>:missing") into short,
// deduplicated sentences. Unknown keys pass through unchanged.
export function describeMissingInputs(keys: string[], names: Map<string, string> = new Map()): string[] {
  const label = (ref: string) => names.get(ref) ?? (uuid.test(ref) ? "An account" : ref);
  const describe = (key: string): string => {
    const named = /^(.+) for (.+)$/.exec(key);
    if (named) return `${describe(named[1]).replace(/^(An account|A balance)/, named[2])}`;
    const [kind, ...rest] = key.split(":");
    if (kind === "balance" || kind === "available-balance") return !rest[1] || rest[1] === "missing" ? `${label(rest[0])} needs a current balance` : rest[1] === "stale" ? `${label(rest[0])} has an out-of-date balance` : `${label(rest[0])} balance is ${rest.slice(1).join(":")}`;
    if (kind === "rate") return `An account needs a ${rest.join(":").replace("->", " to ")} exchange rate`;
    if (kind === "currency") return `Currency ${rest[0]} is not supported`;
    if (kind === "fx") return rest.length > 1 && rest[0] !== "scenario" ? `${label(rest[1])} needs an exchange rate` : "An exchange rate is missing";
    if (kind === "valuation") return `${names.get(rest[0]) ?? "A valuation"} is dated in the future`;
    if (kind === "debt") return `A debt ${rest.slice(1).join(":") || "needs repayment terms"}`;
    if (kind === "occurrence") return `${rest[0]} on ${rest[1]}: evidence changed, review the association`;
    return key;
  };
  return [...new Set(keys.map(describe))];
}

/** The note beside a total that counts older valuations: how many, which, and from when. */
export function describeOutdated(items: { name: string; asOf: string }[], date: (value: string) => string = value => value): string {
  const dates = [...new Set(items.map(item => item.asOf))].sort().reverse();
  const groups = dates.map(asOf => `${items.filter(item => item.asOf === asOf).map(item => item.name).join(", ")} (${date(asOf)})`);
  return `${items.length} ${items.length === 1 ? "valuation is not from today and uses its" : "valuations are not from today and use their"} last known value: ${groups.join("; ")}`;
}

export function formatInputAmount(amountMinor: bigint | string | number, currencyCode: string): string {
  const value = exactMinor(amountMinor);
  const abs = value < 0n ? -value : value;
  const digits = minorDigits(currencyCode);
  const divisor = 10n ** BigInt(digits);
  const whole = abs / divisor;
  if (digits === 0) {
    return `${value < 0n ? "-" : ""}${whole}`;
  }
  const fraction = (abs % divisor).toString().padStart(digits, "0");
  return `${value < 0n ? "-" : ""}${whole}.${fraction}`;
}

import { z } from "zod";
import { minorDigits } from "./fx";

const period = z.object({ from: z.iso.date(), to: z.iso.date() }).strict().refine(p => p.from <= p.to, "From date is after to date");
const entity = z.union([z.object({ id: z.uuid() }).strict(), z.object({ name: z.string().trim().min(1).max(120) }).strict()]);
const entityFilter = z.object({ include: z.array(entity).max(100).optional(), exclude: z.array(entity).max(100).optional() }).strict();
const labelFilter = z.object({ include: z.array(z.string().trim().min(1).max(120)).max(100).optional(), exclude: z.array(z.string().trim().min(1).max(120)).max(100).optional() }).strict();
export const investigationSchema = z.object({
  version: z.literal(1), period, comparison: period.optional(),
  accounts: entityFilter.optional(), categories: entityFilter.optional(), merchants: entityFilter.optional(),
  tags: labelFilter.optional(), events: labelFilter.optional(),
  statuses: z.array(z.enum(["posted", "pending"])).min(1).max(2).default(["posted"]),
  classifications: z.enum(["resolved", "all", "unresolved"]).default("resolved"),
  kinds: z.array(z.enum(["ordinary", "refund", "transfer"])).min(1).max(3).default(["ordinary", "refund"]),
  currencyPolicy: z.discriminatedUnion("mode", [
    z.object({ mode: z.literal("original"), currencies: z.array(z.string().regex(/^[A-Z]{3}$/)).min(1).max(50).optional() }).strict(),
    z.object({ mode: z.literal("base"), currency: z.string().regex(/^[A-Z]{3}$/).refine(c => { try { minorDigits(c); return true; } catch { return false; } }) }).strict(),
  ]).default({ mode: "original" }),
  metric: z.enum(["spending", "income", "net", "signed", "absolute", "count"]).default("spending"),
  groupBy: z.array(z.enum(["account", "category", "merchant", "tag", "event", "date", "month", "kind", "status"])).max(5).default([]).refine(a => new Set(a).size === a.length, "Duplicate grouping dimension"),
  sort: z.enum(["delta-desc", "delta-asc", "absolute-delta-desc", "current-desc", "current-asc", "key"]).default("absolute-delta-desc"),
  page: z.object({ size: z.number().int().min(1).max(100).default(25), cursor: z.string().max(1000).optional(), groupKey: z.string().max(2000).optional(), period: z.enum(["current", "comparison", "both"]).default("both") }).strict().default({ size: 25, period: "both" }),
}).strict();
export type InvestigationSpec = z.infer<typeof investigationSchema>;

