6	import { investigationSchema, type InvestigationSpec } from "./investigation-schema";
7	export { investigationSchema, type InvestigationSpec } from "./investigation-schema";
8	export type InvestigationRow = {
9	  id: string; parentId: string; accountId: string; categoryId: string | null; merchantId: string | null;
10	  date: string; amountMinor: string; currency: string; status: "posted" | "pending"; kind: "ordinary" | "refund" | "transfer";
11	  tags: string[]; event: string | null; reviewReasons: string[]; version: number; description: string;
12	  sourceVersions?: unknown; refundOfId?: string | null;
13	};
14	export type InvestigationEntities = Record<"accounts" | "categories" | "merchants", { id: string; name: string }[]> & { labels?: { tags: string[]; events: string[] } };
15	const entityKeys = ["accounts", "categories", "merchants"] as const;
16	const normalized = (value: string) => value.normalize("NFKC").trim().toLocaleLowerCase("en");
17	
18	/** Resolve only owned entities; ambiguity is a correction request, never a guessed ID. */
19	export function resolveInvestigation(input: unknown, entities: InvestigationEntities): InvestigationSpec {
20	  const spec = investigationSchema.parse(input);
21	  for (const key of entityKeys) {
22	    const filter = spec[key];
23	    if (!filter) continue;
24	    for (const operation of ["include", "exclude"] as const) {
25	      filter[operation] = filter[operation]?.map(ref => {
26	        const matches = entities[key].filter(e => "id" in ref ? e.id === ref.id : normalized(e.name) === normalized(ref.name));
27	        if (!matches.length) throw new Error(`Unknown owned ${key}: ${"id" in ref ? ref.id : ref.name}`);
28	        if (matches.length !== 1) throw new Error(`Ambiguous ${key}: ${"name" in ref ? ref.name : ref.id}; choose an ID from the owned entity list`);
29	        return { id: matches[0].id };
30	      });
31	    }
32	  }
33	  for (const key of ["tags", "events"] as const) {
34	    const filter = spec[key], labels = entities.labels?.[key];
35	    if (!filter || !labels) continue;
36	    for (const operation of ["include", "exclude"] as const) filter[operation] = filter[operation]?.map(value => {
37	      const owned = labels.filter(label => normalized(label) === normalized(value)).sort()[0];
38	      if (!owned) throw new Error(`Unknown owned ${key}: ${value}`);
39	      // These entities are stored as text labels, not UUIDs. Use the existing stable label.
40	      return owned;
41	    });
42	  }
43	  return spec;
44	}
45	
46	// Sort object keys and set-valued query fields so equivalent requests share identities.
47	function canonical(value: unknown): unknown {
48	  if (Array.isArray(value)) return value.map(canonical);
49	  if (value && typeof value === "object") return Object.fromEntries(Object.entries(value).sort(([a], [b]) => a.localeCompare(b)).map(([k, v]) => [k, canonical(v)]));
50	  return value;
51	}
52	export const investigationIdentity = (value: unknown) => createHash("sha256").update(JSON.stringify(canonical(value))).digest("hex");
53	const abs = (value: bigint) => value < 0n ? -value : value;
54	const compare = (a: bigint, b: bigint) => a < b ? -1 : a > b ? 1 : 0;
55	function entityMatches(filter: InvestigationSpec["accounts"], id: string | null) {
56	  if ([...(filter?.include ?? []), ...(filter?.exclude ?? [])].some(ref => !("id" in ref))) throw new Error("Resolve entity names before querying");
57	  const included = filter?.include;
58	  return (!included?.length || included.some(ref => "id" in ref && ref.id === id)) && !filter?.exclude?.some(ref => "id" in ref && ref.id === id);
59	}
60	function labelsMatch(filter: InvestigationSpec["tags"], labels: string[]) {
61	  const values = labels.map(normalized);
62	  return (!filter?.include?.length || filter.include.some(label => values.includes(normalized(label)))) && !filter?.exclude?.some(label => values.includes(normalized(label)));
63	}
64	function metricValue(row: InvestigationRow, metric: InvestigationSpec["metric"]) {
65	  const amount = BigInt(row.amountMinor);
66	  if (metric === "count") return 1n;
67	  if (metric === "absolute") return abs(amount);
68	  if (metric === "signed") return amount;
69	  // Transfer principals are gross flows, never financial income/spending/net.
70	  if (row.kind === "transfer") return 0n;
71	  if (metric === "net") return amount;
72	  if (metric === "income") return row.kind !== "refund" && amount > 0n ? amount : 0n;
73	  return row.kind === "refund" || amount < 0n ? -amount : 0n;
74	}
75	export function investigationGroup(row: InvestigationRow, dimensions: InvestigationSpec["groupBy"]) {
76	  return Object.fromEntries(dimensions.map(d => [d,
77	    d === "account" ? row.accountId : d === "category" ? row.categoryId : d === "merchant" ? row.merchantId :
78	      // Tags are a set-valued partition: a record belongs once, never once per tag.
79	      d === "tag" ? [...new Set(row.tags)].sort() : d === "event" ? row.event : d === "date" ? row.date : d === "month" ? row.date.slice(0, 7) : row[d],
80	  ]));
81	}
82	export type InvestigationContext = { workspaceId: string; capturedAt: string; sourceCoverage?: unknown; rates?: ExpenditureRate[]; entities?: InvestigationEntities };
83	
84	function allocatedReporting(rows: InvestigationRow[], spec: InvestigationSpec, rates: ExpenditureRate[]) {
85	  if (spec.currencyPolicy.mode !== "base") return null;
86	  if (spec.statuses.some(s => s !== "posted") || spec.classifications !== "resolved" || spec.kinds.includes("transfer")) throw new Error("Base currency accounting requires posted, resolved ordinary/refund records; use original currency for provisional or transfer analysis");
87	  const from = [spec.period.from, spec.comparison?.from].filter((v): v is string => Boolean(v)).sort()[0];
88	  const to = [spec.period.to, spec.comparison?.to].filter((v): v is string => Boolean(v)).sort().at(-1)!;
89	  const report = reportExpenditure(rows.map(r => ({ id: r.id, parentTransactionId: r.parentId, accountId: r.accountId,
90	    amountMinor: BigInt(r.amountMinor), currencyCode: r.currency, postedOn: r.date, status: r.status, kind: r.kind, reviewReasons: r.reviewReasons, version: r.version })), rates, { view: "base", currencyCode: spec.currencyPolicy.currency, from, to });
91	  const allocated = new Map<string, string | null>();
92	  for (const posting of report.postings) {
93	    if (posting.reportingAmountMinor === null || !posting.rate || !posting.rounding) {
94	      for (const child of posting.sourcePostings) allocated.set(child.id, null);
95	      continue;
96	    }
97	    const denominator = BigInt(posting.rounding.scaledDenominator);
98	    const multiplier = BigInt(posting.rate.numerator) * 10n ** BigInt(minorDigits(spec.currencyPolicy.currency));
99	    const shares = posting.sourcePostings.map(child => {
100	      const scaled = BigInt(child.originalAmountMinor) * multiplier;
