/**
 * The question card of a voice call: one typed finance question that every spoken word edits and
 * deterministic code answers. A card only holds owned entities and resolved dates, so it can never
 * carry a guess into `investigate()`.
 */
export type Ref = { id: string; name: string };
/** A resolved date range and how to say it ("last month", "in October"). */
export type Period = { from: string; to: string; say: string };
export type Card = {
  metric: "spending" | "income" | "net" | "count";
  categories: Ref[]; merchants: Ref[]; accounts: Ref[];
  period: Period; comparison?: Period;
  groupBy?: "category" | "merchant" | "account" | "month";
};

const iso = (at: Date) => at.toISOString().slice(0, 10);
const utc = (date: string) => new Date(`${date}T00:00:00Z`);
export const shiftDays = (date: string, days: number) => iso(new Date(utc(date).getTime() + days * 86_400_000));
/** The same day `months` away, clamped to the end of a shorter month. */
export function shiftMonths(date: string, months: number) {
  const at = utc(date), day = at.getUTCDate();
  at.setUTCDate(1);
  at.setUTCMonth(at.getUTCMonth() + months);
  at.setUTCDate(Math.min(day, new Date(Date.UTC(at.getUTCFullYear(), at.getUTCMonth() + 1, 0)).getUTCDate()));
  return iso(at);
}
const monthStart = (date: string, offset = 0) => shiftMonths(`${date.slice(0, 7)}-01`, offset);
const monthEnd = (date: string, offset = 0) => shiftDays(monthStart(date, offset + 1), -1);
// Weeks start on Monday, as everywhere else in Moneo.
const weekStart = (date: string) => shiftDays(date, -((utc(date).getUTCDay() + 6) % 7));

export const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const plural = (count: number, unit: string) => `${count === 1 ? "" : `${count} `}${unit}${count === 1 ? "" : "s"}`;

export const periods = {
  day(today: string, offset: number): Period {
    const date = shiftDays(today, offset);
    return { from: date, to: date, say: offset === 0 ? "today" : offset === -1 ? "yesterday" : `on ${spokenDate(date)}` };
  },
  week(today: string, offset: number): Period {
    const from = shiftDays(weekStart(today), offset * 7);
    return { from, to: shiftDays(from, 6), say: offset === 0 ? "this week" : offset === -1 ? "last week" : `in the week of ${spokenDate(from)}` };
  },
  month(today: string, offset: number): Period {
    const from = monthStart(today, offset);
    return { from, to: monthEnd(today, offset), say: offset === 0 ? "this month" : offset === -1 ? "last month" : monthSay(from, today) };
  },
  year(today: string, offset: number): Period {
    const year = Number(today.slice(0, 4)) + offset;
    return { from: `${year}-01-01`, to: `${year}-12-31`, say: offset === 0 ? "this year" : offset === -1 ? "last year" : `in ${year}` };
  },
  /** A named month: `year` given, or the latest one that has started. */
  named(today: string, month: number, year?: number): Period {
    const current = Number(today.slice(0, 4));
    const resolved = year ?? (month > Number(today.slice(5, 7)) ? current - 1 : current);
    const from = `${resolved}-${String(month).padStart(2, "0")}-01`;
    return { from, to: monthEnd(from), say: monthSay(from, today) };
  },
  /** The last `count` days, weeks or months, ending today. */
  rolling(today: string, count: number, unit: "day" | "week" | "month"): Period {
    const from = unit === "month" ? shiftDays(shiftMonths(today, -count), 1) : shiftDays(today, 1 - count * (unit === "week" ? 7 : 1));
    return { from, to: today, say: `in the last ${plural(count, unit)}` };
  },
  /** The period just before this one: whole months stay whole months, anything else keeps its length. */
  before(period: Period, today: string): Period {
    const wholeMonths = period.from.endsWith("-01") && period.to === monthEnd(period.to);
    if (wholeMonths) {
      const count = (Number(period.to.slice(0, 4)) - Number(period.from.slice(0, 4))) * 12 + Number(period.to.slice(5, 7)) - Number(period.from.slice(5, 7)) + 1;
      const from = monthStart(period.from, -count), to = monthEnd(period.from, -1);
      const say = count === 1 ? periods.month(today, 0).from === period.from ? "last month" : monthSay(from, today)
        : count === 12 && from.slice(5, 7) === "01" ? `in ${from.slice(0, 4)}` : `in the ${plural(count, "month")} before`;
      return { from, to, say };
    }
    const days = Math.round((utc(period.to).getTime() - utc(period.from).getTime()) / 86_400_000) + 1;
    const to = shiftDays(period.from, -1);
    return { from: shiftDays(to, 1 - days), to, say: days === 1 ? `on ${spokenDate(to)}` : days === 7 ? "in the week before" : `in the ${plural(days, "day")} before` };
  },
};

function monthSay(from: string, today: string) {
  const name = MONTHS[Number(from.slice(5, 7)) - 1];
  // A month within the last year needs no year to be understood.
  return from > shiftMonths(today, -12) && from <= today ? `in ${name}` : `in ${name} ${from.slice(0, 4)}`;
}
function spokenDate(date: string) {
  return `${MONTHS[Number(date.slice(5, 7)) - 1]} ${Number(date.slice(8, 10))}`;
}

export const emptyCard = (today: string): Card => ({ metric: "spending", categories: [], merchants: [], accounts: [], period: periods.month(today, 0) });

const range = ({ from, to }: Period) => ({ from, to });
const include = (refs: Ref[]) => refs.length ? { include: refs.map(ref => ({ id: ref.id })) } : undefined;
/** The card as input for `investigate()`: the query Moneo already knows how to answer and link to. */
export function toInvestigation(card: Card) {
  return {
    version: 1 as const, period: range(card.period), ...(card.comparison ? { comparison: range(card.comparison) } : {}),
    accounts: include(card.accounts), categories: include(card.categories), merchants: include(card.merchants),
    metric: card.metric, groupBy: card.groupBy ? [card.groupBy] : [], sort: card.groupBy === "month" ? "key" as const : "current-desc" as const,
  };
}

