import { minorDigits } from "@/lib/finance/fx";
import type { investigate, InvestigationEntities } from "@/lib/finance/investigation";
import type { Card } from "./voice-query";

const ONES = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"];
const TENS = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"];
const SCALES = ["", " thousand", " million", " billion", " trillion"];

function below1000(value: number) {
  const hundreds = Math.floor(value / 100), rest = value % 100;
  const tail = rest < 20 ? ONES[rest] : TENS[Math.floor(rest / 10)] + (rest % 10 ? `-${ONES[rest % 10]}` : "");
  return hundreds ? `${ONES[hundreds]} hundred${rest ? ` ${tail}` : ""}` : tail;
}

/** A whole number in words, so no speech engine has to guess how to read digits. */
export function numberWords(value: bigint | number): string {
  let rest = BigInt(value);
  if (rest < 0n) return `minus ${numberWords(-rest)}`;
  if (rest < 1000n) return below1000(Number(rest));
  const groups: string[] = [];
  for (let scale = 0; rest > 0n; scale++, rest /= 1000n) {
    // Past trillions nobody says the name; spell the digits rather than invent one.
    if (scale >= SCALES.length) return BigInt(value).toString().split("").map(digit => ONES[Number(digit)]).join(" ");
    const group = Number(rest % 1000n);
    if (group) groups.unshift(below1000(group) + SCALES[scale]);
  }
  return groups.join(" ");
}

export function yearWords(year: number) {
  return year >= 2010 && year <= 2099 ? `twenty ${numberWords(year % 100)}` : numberWords(year);
}

const MINOR: Record<string, [string, string]> = {
  GBP: ["penny", "pence"],
  ...Object.fromEntries(["EUR", "USD", "CAD", "AUD", "NZD", "SGD", "HKD"].map(code => [code, ["cent", "cents"]] as const)),
};

/** An exact amount in words: "three hundred twelve euros and forty cents". Never rounds. */
export function speakMoney(amountMinor: bigint | string, currency: string): string {
  const value = BigInt(amountMinor), abs = value < 0n ? -value : value;
  const digits = minorDigits(currency), divisor = 10n ** BigInt(digits);
  const whole = abs / divisor, fraction = abs % divisor;
  const unit = (count: bigint) => new Intl.NumberFormat("en", { style: "currency", currency, currencyDisplay: "name", maximumFractionDigits: 0 })
    .formatToParts(count === 1n ? 1 : 2).find(part => part.type === "currency")?.value ?? currency;
  const sign = value < 0n ? "minus " : "";
  if (!fraction) return `${sign}${numberWords(whole)} ${unit(whole)}`;
  const minor = MINOR[currency];
  if (minor && digits === 2) {
    const small = `${numberWords(fraction)} ${minor[fraction === 1n ? 0 : 1]}`;
    return sign + (whole ? `${numberWords(whole)} ${unit(whole)} and ${small}` : small);
  }
  const decimals = fraction.toString().padStart(digits, "0").split("").map(digit => ONES[Number(digit)]).join(" ");
  return `${sign}${numberWords(whole)} point ${decimals} ${unit(2n)}`;
}

/**
 * A spoken answer in pieces, each tied to the part of the card it depends on. The number comes last,
 * so a correction that arrives while the lead-in is spoken changes what is said next instead of
 * forcing a restart.
 */
export type Segment = { slot: "scope" | "period" | "metric" | "value" | "comparison" | "caveat"; text: string };
type Result = ReturnType<typeof investigate>;

const list = (items: string[]) => items.length < 3 ? items.join(" and ") : `${items.slice(0, -1).join(", ")} and ${items.at(-1)}`;
const capital = (text: string) => text.charAt(0).toUpperCase() + text.slice(1);
const count = (value: bigint) => `${numberWords(value)} transaction${value === 1n ? "" : "s"}`;
const amount = (card: Card, minor: bigint, currency: string) => card.metric === "count" ? count(minor) : speakMoney(minor, currency);
const magnitude = (value: bigint) => value < 0n ? -value : value;

function scope(card: Card) {
  return [
    card.categories.length ? `${card.metric === "spending" ? "on" : "for"} ${list(card.categories.map(ref => ref.name))}` : "",
    card.merchants.length ? `at ${list(card.merchants.map(ref => ref.name))}` : "",
