import { describe, expect, it } from "vitest";
import { investigate, type InvestigationEntities, type InvestigationRow } from "@/lib/finance/investigation";
import { emptyCard, periods, toInvestigation, type Card } from "./voice-query";
import { editCard } from "./voice-query-editor";
import { answerSegments, numberWords, rebind, speak, speakMoney } from "./voice-say";

const today = "2026-11-15"; // a Sunday
const id = (n: number) => `00000000-0000-4000-8000-${String(n).padStart(12, "0")}`;
const entities: InvestigationEntities = {
  categories: [{ id: id(1), name: "Groceries" }, { id: id(2), name: "Restaurants" }, { id: id(3), name: "Eating out" }, { id: id(4), name: "Savings" }],
  merchants: [{ id: id(11), name: "Rewe" }, { id: id(12), name: "Deutsche Bahn" }],
  accounts: [{ id: id(21), name: "N26" }, { id: id(22), name: "Savings" }],
};
const edit = (text: string, base: Card | null = null) => editCard(base, text, entities, today);
const names = (card: Card) => ({ categories: card.categories.map(ref => ref.name), merchants: card.merchants.map(ref => ref.name), accounts: card.accounts.map(ref => ref.name) });
const range = (period?: { from: string; to: string }) => period && `${period.from}..${period.to}`;

describe("speaking money", () => {
  it("says the exact amount in words for each kind of currency", () => {
    expect(speakMoney(31240n, "EUR")).toBe("three hundred twelve euros and forty cents");
    expect(speakMoney(100n, "EUR")).toBe("one euro");
    expect(speakMoney("-5", "USD")).toBe("minus five cents");
    expect(speakMoney(101n, "GBP")).toBe("one British pound and one penny");
    expect(speakMoney(5000n, "JPY")).toBe("five thousand Japanese yen");
    expect(speakMoney(1005n, "KWD")).toBe("one point zero zero five Kuwaiti dinars");
    expect(speakMoney(123456789012n, "EUR")).toBe("one billion two hundred thirty-four million five hundred sixty-seven thousand eight hundred ninety euros and twelve cents");
  });
  it("never rounds a number too large to name", () => {
    expect(numberWords(10n ** 15n)).toBe(["one", ...Array(15).fill("zero")].join(" "));
  });
});

describe("periods", () => {
  it("resolves spoken periods to exact dates", () => {
    expect(range(periods.week(today, 0))).toBe("2026-11-09..2026-11-15");
    expect(range(periods.month(today, -1))).toBe("2026-10-01..2026-10-31");
    expect(range(periods.named(today, 12))).toBe("2025-12-01..2025-12-31");
    expect(range(periods.rolling("2026-03-31", 1, "month"))).toBe("2026-03-01..2026-03-31");
    expect(range(periods.rolling(today, 30, "day"))).toBe("2026-10-17..2026-11-15");
    expect(periods.before(periods.month(today, 0), today)).toEqual({ from: "2026-10-01", to: "2026-10-31", say: "last month" });
    expect(range(periods.before(periods.rolling(today, 7, "day"), today))).toBe("2026-11-02..2026-11-08");
  });
});

describe("editing the card from speech", () => {
  it("fills a card from a full question", () => {
    const { card, leftover } = edit("Hey Moneo, how much did I spend on groceries at Rewe last month?");
    expect(leftover).toEqual([]);
    expect(card.metric).toBe("spending");
