import { describe, expect, it } from "vitest";
import { investigate, type InvestigationEntities, type InvestigationRow } from "@/lib/finance/investigation";
import { emptyCard, periods, toInvestigation, type Card } from "./voice-query";
import { editCard } from "./voice-query-editor";
import { answerSegments, numberWords, rebind, speak, speakMoney } from "./voice-say";

const today = "2026-11-15"; // a Sunday
const id = (n: number) => `00000000-0000-4000-8000-${String(n).padStart(12, "0")}`;
const entities: InvestigationEntities = {
  categories: [{ id: id(1), name: "Groceries" }, { id: id(2), name: "Restaurants" }, { id: id(3), name: "Eating out" }, { id: id(4), name: "Savings" }],
  merchants: [{ id: id(11), name: "Rewe" }, { id: id(12), name: "Deutsche Bahn" }],
  accounts: [{ id: id(21), name: "N26" }, { id: id(22), name: "Savings" }],
};
const edit = (text: string, base: Card | null = null) => editCard(base, text, entities, today);
const names = (card: Card) => ({ categories: card.categories.map(ref => ref.name), merchants: card.merchants.map(ref => ref.name), accounts: card.accounts.map(ref => ref.name) });
const range = (period?: { from: string; to: string }) => period && `${period.from}..${period.to}`;

describe("speaking money", () => {
  it("says the exact amount in words for each kind of currency", () => {
    expect(speakMoney(31240n, "EUR")).toBe("three hundred twelve euros and forty cents");
    expect(speakMoney(100n, "EUR")).toBe("one euro");
    expect(speakMoney("-5", "USD")).toBe("minus five cents");
    expect(speakMoney(101n, "GBP")).toBe("one British pound and one penny");
    expect(speakMoney(5000n, "JPY")).toBe("five thousand Japanese yen");
    expect(speakMoney(1005n, "KWD")).toBe("one point zero zero five Kuwaiti dinars");
    expect(speakMoney(123456789012n, "EUR")).toBe("one billion two hundred thirty-four million five hundred sixty-seven thousand eight hundred ninety euros and twelve cents");
  });
  it("never rounds a number too large to name", () => {
    expect(numberWords(10n ** 15n)).toBe(["one", ...Array(15).fill("zero")].join(" "));
  });
});

describe("periods", () => {
  it("resolves spoken periods to exact dates", () => {
    expect(range(periods.week(today, 0))).toBe("2026-11-09..2026-11-15");
    expect(range(periods.month(today, -1))).toBe("2026-10-01..2026-10-31");
    expect(range(periods.named(today, 12))).toBe("2025-12-01..2025-12-31");
    expect(range(periods.rolling("2026-03-31", 1, "month"))).toBe("2026-03-01..2026-03-31");
    expect(range(periods.rolling(today, 30, "day"))).toBe("2026-10-17..2026-11-15");
    expect(periods.before(periods.month(today, 0), today)).toEqual({ from: "2026-10-01", to: "2026-10-31", say: "last month" });
    expect(range(periods.before(periods.rolling(today, 7, "day"), today))).toBe("2026-11-02..2026-11-08");
  });
});

describe("editing the card from speech", () => {
  it("fills a card from a full question", () => {
    const { card, leftover } = edit("Hey Moneo, how much did I spend on groceries at Rewe last month?");
    expect(leftover).toEqual([]);
    expect(card.metric).toBe("spending");
    expect(names(card)).toEqual({ categories: ["Groceries"], merchants: ["Rewe"], accounts: [] });
    expect(range(card.period)).toBe("2026-10-01..2026-10-31");
  });

  it("lets the last word win when the owner corrects themselves", () => {
    expect(range(edit("how much did I spend last month, no wait, this month").card.period)).toBe("2026-11-01..2026-11-30");
    expect(names(edit("what did I spend on groceries, sorry, I mean restaurants").card).categories).toEqual(["Restaurants"]);
    expect(names(edit("what did I spend on groceries and eating out").card).categories).toEqual(["Groceries", "Eating out"]);
    const compared = edit("groceries spending this month compared to last month, actually October twenty twenty five").card;
    expect([range(compared.period), range(compared.comparison)]).toEqual(["2026-11-01..2026-11-30", "2025-10-01..2025-10-31"]);
  });

  it("edits the previous card on a short follow-up and starts over on a new question", () => {
    const first = edit("how much did I spend on groceries last month").card;
    const next = edit("and what about restaurants?", first).card;
    expect([names(next).categories, range(next.period)]).toEqual([["Restaurants"], "2026-10-01..2026-10-31"]);
    const interrupted = edit("not groceries, restaurants", first).card;
    expect(names(interrupted).categories).toEqual(["Restaurants"]);
    const fresh = edit("how much did I earn this year", next).card;
    expect([fresh.metric, names(fresh).categories, range(fresh.period)]).toEqual(["income", [], "2026-01-01..2026-12-31"]);
    expect(names(edit("and how much did I earn?", first).card).categories).toEqual([]);
  });

  it("reads comparisons, counts and breakdowns", () => {
    expect(range(edit("did I spend more than the month before").card.comparison)).toBe("2026-10-01..2026-10-31");
    expect(range(edit("how does my spending compare").card.comparison)).toBe("2026-10-01..2026-10-31");
    expect(edit("how many times did I pay Deutsche Bahn in the last 3 months").card).toMatchObject({ metric: "count", period: { from: "2026-08-16", to: "2026-11-15" } });
    expect(edit("where did my money go in March").card).toMatchObject({ groupBy: "category", period: { from: "2026-03-01" } });
  });

  it("reports every word it could not account for, so a changed meaning is never answered", () => {
    expect(edit("how much did I spend on groceries excluding the trip to Rome").leftover).toEqual(["excluding", "trip", "rome"]);
    expect(edit("how much did I spend on everything but not groceries").leftover).toContain("not");
    expect(edit("how much can I spend this month").leftover).toEqual([]); // safe only because "can" changes nothing typed; see budget test below
    expect(edit("am I over budget this month").leftover).toEqual(["am", "budget"]);
    expect(edit("how much is in savings").leftover).toEqual(["savings"]); // a category and an account share the name
    expect(edit("tell me more").touched).toBe(false);
    expect(edit("may I ask what I spent").card.period).toEqual(emptyCard(today).period);
  });

  it("gives the same card for the finished sentence however the words arrive", () => {
    const sentence = "how much did I spend at Rewe last week no this week compared to the week before";
    const final = edit(sentence).card;
    const parts = sentence.split(" ");
    for (let length = 1; length <= parts.length; length++) edit(parts.slice(0, length).join(" ")); // every partial transcript parses
    expect([range(final.period), range(final.comparison), names(final).merchants]).toEqual(["2026-11-09..2026-11-15", "2026-11-02..2026-11-08", ["Rewe"]]);
  });
});

describe("answering the card", () => {
  const row = (n: number, values: Partial<InvestigationRow>): InvestigationRow => ({
    id: id(100 + n), parentId: id(100 + n), accountId: id(21), categoryId: id(1), merchantId: id(11), date: "2026-11-03", amountMinor: "-1000", currency: "EUR",
    status: "posted", kind: "ordinary", tags: [], event: null, reviewReasons: [], version: 1, description: "", ...values,
  });
  const rows = [
    row(1, { amountMinor: "-31240" }), row(2, { amountMinor: "-2000", currency: "USD" }),
    row(3, { amountMinor: "-27240", date: "2026-10-09" }), row(4, { amountMinor: "-9900", categoryId: id(2), merchantId: null }),
    row(5, { amountMinor: "-500", reviewReasons: ["needs-review"], categoryId: id(2) }),
  ];
  const answer = (text: string) => {
    const { card } = edit(text);
    const segments = answerSegments(card, investigate(toInvestigation(card), rows, { workspaceId: id(0), capturedAt: `${today}T00:00:00Z` }), entities);
    return segments && speak(segments);
  };

  it("puts the number last and keeps currencies apart", () => {
    expect(answer("how much did I spend on groceries this month")).toBe("On Groceries this month, you spent three hundred twelve euros and forty cents, plus twenty US dollars.");
    expect(answer("how much did I spend at Rewe yesterday")).toBe("At Rewe yesterday, you spent nothing.");
  });

  it("says the difference and warns when rows are left out", () => {
    const { card } = edit("how much did I spend on groceries in euros");
    expect(card.categories).toHaveLength(1);
    const eur = rows.filter(item => item.currency === "EUR");
    const spoken = (text: string) => {
      const edited = edit(text).card;
      return speak(answerSegments(edited, investigate(toInvestigation(edited), eur, { workspaceId: id(0), capturedAt: `${today}T00:00:00Z` }), entities)!);
    };
    expect(spoken("groceries spending this month versus last month")).toBe("On Groceries this month, you spent three hundred twelve euros and forty cents, forty euros more than last month.");
    expect(spoken("what did I spend on restaurants this month")).toBe("On Restaurants this month, you spent ninety-nine euros. Some transactions still need review, so this may be incomplete.");
    expect(spoken("where did my money go this month")).toBe("This month, you spent the most on Groceries, three hundred twelve euros and forty cents; then Restaurants, ninety-nine euros. Some transactions still need review, so this may be incomplete.");
  });

  it("hands a ranking across currencies to the chat model instead of guessing", () => {
    expect(answer("where did my money go this month")).toBeNull();
  });

  it("resumes speech at the first piece a correction changed", () => {
    const say = (text: string) => {
      const { card } = edit(text);
      return answerSegments(card, investigate(toInvestigation(card), rows, { workspaceId: id(0), capturedAt: `${today}T00:00:00Z` }), entities)!;
    };
    const before = say("what did I spend on groceries this month"), after = say("what did I spend on groceries last month");
    // Only "On Groceries" was said when the owner changed the month: nothing has to be taken back.
    expect(rebind(before.slice(0, 1), after)).toEqual({ from: 1, repair: false });
    expect(rebind(before.slice(0, 2), after)).toEqual({ from: 1, repair: true });
  });
});

