import { investigate, type InvestigationContext, type InvestigationEntities, type InvestigationRow } from "@/lib/finance/investigation";
import { toInvestigation, type Card } from "./voice-query";
import { editCard } from "./voice-query-editor";
import { answerSegments, speak, type Segment } from "./voice-say";

/** What a call keeps in memory so questions are answered without a database or a model. */
export type CallData = { rows: InvestigationRow[]; context: InvestigationContext; entities: InvestigationEntities; today: string };

/**
 * The fast path of a call: the words so far become a card, and code answers it from the rows in
 * memory. Null means "not mine": a word was not understood or the answer needs more than one
 * sentence, and the chat model takes the turn. It reads only; nothing here can write.
 */
export function fastAnswer(base: Card | null, utterance: string, data: CallData): { card: Card; segments: Segment[]; text: string } | null {
  const { card, leftover, touched } = editCard(base, utterance, data.entities, data.today);
  if (!touched || leftover.length) return null;
  const segments = answerSegments(card, investigate(toInvestigation(card), data.rows, data.context), data.entities);
  return segments && { card, segments, text: speak(segments) };
}
EOF
