s = s.replace(row, "| Check audio before it plays | Offline round-trip testing (AssemblyAI guide and others); a patent on checking synthesised speech before playback (found by the audit, section 7) | Not a new idea. Only the cheap form is ours: compare digit sequences on a small CPU recogniser |");
const marker = "## 6. Sources";
if (!s.includes(marker)) throw new Error("marker missing");
s = s.replace(marker, fs.readFileSync(sections, "utf8") + "## 10. Sources");
s = s.trimEnd() + "\n- Audit additions: Zhou et al. ACL 2022 (online semantic parsing for latency reduction); TERTiUS https://arxiv.org/abs/2307.04008 ; EchoChain https://arxiv.org/abs/2604.16456 ; Buschmeier, Baumann, Dosch, Kopp, Schlangen, SIGDIAL 2012; Trummer, CiceroDB; Evizeon (IEEE VAST 2017); Disfl-QA\n";
fs.writeFileSync(log, s);

