<!doctype html>
<html><head><meta charset="utf-8"><title>Live-query call plan</title></head><body>
<style>
  .w{font-family:var(--font-sans);color:var(--foreground);font-size:13px;line-height:1.35}
  h3{font-size:14px;margin:22px 0 10px} h3:first-child{margin-top:4px}
  .mut{color:var(--muted-foreground)} .sm{font-size:11px}
  .flow{display:flex;flex-wrap:wrap;gap:6px;align-items:stretch}
  .n{flex:1 1 92px;border:1px solid var(--border);border-radius:var(--radius);padding:8px;background:var(--card);text-align:center}
  .n b{display:block} .n span{display:block;font-size:11px;color:var(--muted-foreground);margin-top:2px}
  .a{align-self:center;color:var(--muted-foreground)}
  .hot{border-color:var(--chart-1)} .code{border-color:var(--chart-2)} .big{border-color:var(--chart-3);border-style:dashed}
  .loop{margin-top:6px;border:1px dashed var(--border);border-radius:var(--radius);padding:6px 8px;text-align:center;font-size:11px;color:var(--muted-foreground)}
  .cards{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
  .q{flex:1 1 150px;border:1px solid var(--border);border-radius:var(--radius);background:var(--card);padding:8px}
  .q i{display:block;font-style:normal;font-size:11px;color:var(--muted-foreground);margin-bottom:6px}
  .q div{display:flex;justify-content:space-between;font-size:12px;padding:2px 4px;border-radius:4px}
  .q div span:first-child{color:var(--muted-foreground)}
  .chg{background:var(--chart-1);color:var(--background)} .chg span:first-child{color:var(--background)!important}
  .tl{display:grid;grid-template-columns:52px 1fr;gap:4px 8px;align-items:center;margin-bottom:4px}
  .t{position:relative;height:24px;background:var(--secondary);border-radius:4px}
